mapper.select:
SELECT fi.* ,dst.security_type_name ,( SELECT sr.rating_code FROM rrs_stock_rating sr WHERE sr.stock_code = fi.stock_code AND sr.is_deleted = 0 ORDER BY sr.rating_date DESC ,sr.id DESC LIMIT 1 ) latest_rating ,( SELECT sr.rating_code FROM rrs_stock_rating sr WHERE sr.stock_code = fi.stock_code AND sr.is_deleted = 0 ORDER BY sr.rating_date DESC ,sr.id DESC LIMIT 1 OFFSET 1 ) previous_rating FROM rrs_stockinfo fi INNER JOIN dict_security_type dst ON dst.security_type = fi.security_type AND dst.category_type = 'stock' AND dst.is_deleted = 0
AND fi.is_deleted = 0 AND fi.security_status = 'L'
AND fi.stock_code LIKE CONCAT('%', #{stockCode}, '%')
AND fi.stock_short_name LIKE CONCAT('%', #{stockShortName}, '%')
AND ( fi.stock_name LIKE CONCAT('%', #{stockName}, '%') OR fi.stock_short_name LIKE CONCAT('%', #{stockName}, '%') )
AND fi.industry_code = #{industryCode}
AND fi.market_code = #{marketCode}
AND fi.security_type = #{securityType}
ORDER BY fi.stock_code ASC

SELECT * FROM rrs_stockinfo WHERE is_deleted = 0 AND stock_code IN
#{stockCode}
ORDER BY id ASC FOR UPDATE

SELECT al.* ,fd.name AS flowName FROM ip_adjust_log_stock al LEFT JOIN wf_flow_definition fd ON fd.id = al.flow_id
AND al.stock_code = #{stockCode} AND al.is_deleted = 0
AND al.adjust_batch_no = #{adjustBatchNo}
AND al.id = #{adjustLogId}
AND al.audit_status NOT IN ('-1', '20', '21', '99')
ORDER BY al.submit_time DESC ,al.id DESC

SELECT step.* FROM ip_adjust_step_stock step
AND step.adjust_batch_no = #{adjustBatchNo}
AND step.adjust_log_id = #{adjustLogId}
ORDER BY step.sort_order ASC ,step.start_time ASC ,step.id ASC

SELECT step.* FROM ip_adjust_step_stock step
step.adjust_batch_no = #{adjustBatchNo}
step.adjust_log_id = #{adjustLogId}
ORDER BY step.sort_order ASC ,step.start_time ASC ,step.id ASC

SELECT *
FROM ip_adjust_step_stock
WHERE adjust_log_id = #{adjustLogId}
  AND adjust_batch_no = #{adjustBatchNo}
  AND flow_node_id = #{flowNodeId}
  AND handler_id = #{handlerId}
  AND step_status = 'pending'
ORDER BY id ASC
LIMIT 1

SELECT COUNT(1)
FROM ip_adjust_step_stock
WHERE adjust_log_id = #{adjustLogId}
  AND adjust_batch_no = #{adjustBatchNo}
  AND flow_node_id = #{flowNodeId}
  AND step_status = 'pending'

mapper.update:
UPDATE ip_adjust_step_stock
SET step_status = #{stepStatus}
   ,process_action = #{processAction}
   ,process_comment = #{processComment}
   ,process_time = NOW()
   ,updt_time = NOW()
WHERE id = #{id}
  AND step_status = 'pending'

UPDATE ip_adjust_step_stock
SET step_status = #{stepStatus}
   ,process_action = 'skipped'
   ,process_time = NOW()
   ,updt_time = NOW()
WHERE adjust_log_id = #{adjustLogId}
  AND adjust_batch_no = #{adjustBatchNo}
  AND flow_node_id = #{flowNodeId}
  AND step_status = 'pending'
  AND id != #{id}

UPDATE ip_adjust_log_stock
SET updt_time = NOW()

   ,adjust_reason = #{adjustReason}


   ,adjust_advice = #{adjustAdvice}


    is_deleted = 0
    AND audit_status = '11'
    AND adjust_batch_no = #{adjustBatchNo}

mapper.select:
SELECT COUNT(1) > 0
FROM ip_pool_open_day
WHERE pool_id = #{poolId}
  AND begin_date <= #{today}
  AND end_date >= #{today}
  AND is_deleted = 0

SELECT COUNT(1) > 0
FROM ip_adjust_log_stock al
INNER JOIN ip_adjust_step_stock step ON step.adjust_batch_no = al.adjust_batch_no
WHERE al.stock_code = #{stockCode}
  AND al.target_pool_id = #{targetPoolId}
  AND al.audit_status IN ('00', '11')
  AND al.is_deleted = 0
  AND step.step_status = 'pending'

    AND al.adjust_batch_no != #{excludedBatchNo}

SELECT COUNT(1) > 0
FROM ip_adjust_log_stock
WHERE stock_code = #{stockCode}
  AND target_pool_id = #{targetPoolId}
  AND adjust_mode = #{adjustMode}
  AND adjuster_id = #{adjusterId}
  AND submit_time >= #{recentSince}
  AND is_deleted = 0

mapper.insert:
INSERT INTO ip_adjust_log_stock (
    stock_code
   ,stock_name
   ,stock_short_name
   ,security_type
   ,industry_code
   ,industry_name
   ,latest_rating
   ,previous_rating
   ,adjust_type
   ,adjust_mode
   ,adjust_batch_no
   ,target_pool_id
   ,target_pool_name
   ,pool_type
   ,flow_id
   ,flow_key
   ,flow_type
   ,audit_status
   ,adjuster_id
   ,adjuster_name
   ,adjust_reason
   ,adjust_advice
   ,submit_time
   ,audit_time
   ,is_deleted
   ,crte_time
   ,updt_time
) VALUES (
    #{stockCode}
   ,#{stockName}
   ,#{stockShortName}
   ,#{securityType}
   ,#{industryCode}
   ,#{industryName}
   ,#{latestRating}
   ,#{previousRating}
   ,#{adjustType}
   ,#{adjustMode}
   ,#{adjustBatchNo}
   ,#{targetPoolId}
   ,#{targetPoolName}
   ,#{poolType}
   ,#{flowId}
   ,#{flowKey}
   ,#{flowType}
   ,#{auditStatus}
   ,#{adjusterId}
   ,#{adjusterName}
   ,#{adjustReason}
   ,#{adjustAdvice}
   ,#{submitTime}

   ,CASE WHEN #{auditStatus} = '20' THEN NOW() ELSE NULL END
   ,0
   ,NOW()
   ,NOW()
)
